from math import gcd
class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        ans = 0
        for i in range(len(nums)):
            fd = int(str(nums[i])[0])
            for j in range(i + 1, len(nums)):
                if gcd(fd, nums[j] % 10) == 1:
                    ans += 1
        return ans

