from math import gcd
class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        fc = [0]*10; lc = [0]*10; self_ok = 0
        for x in nums:
            f = int(str(x)[0]); l = x % 10
            fc[f] += 1; lc[l] += 1
            if gcd(f, l) == 1: self_ok += 1
        return sum(fc[f]*lc[l] for f in range(1,10) for l in range(1,10) if gcd(f,l)==1) - self_ok

