class Solution {
    public int countBeautifulPairs(int[] nums) {
        long[] fc = new long[10], lc = new long[10]; long selfOk = 0, ans = 0;
        for (int x : nums) {
            int f = String.valueOf(x).charAt(0)-'0', l = x%10;
            fc[f]++; lc[l]++;
            if (gcd(f,l)==1) selfOk++;
        }
        for (int f=1;f<10;f++) for (int l=1;l<10;l++)
            if (gcd(f,l)==1) ans += fc[f]*lc[l];
        return (int)(ans-selfOk);
    }
    private int gcd(int a,int b){return b==0?a:gcd(b,a%b);}
}

